function allScenarios(){return [scenario,[2,"s02-headline-poison","Headline Poison","A story can be true and still not pay the contract."],[3,"s03-liquidity-mirage","The Liquidity Mirage","A price you cannot exit is decoration."],[4,"s04-whale-shadow","The Whale Shadow","Copying size without motive is surrender."]].map((s,i)=>Array.isArray(s)?{id:s[1],title:s[2],scar:s[3],status:"locked",module:"second-stake",scenario_number:s[0]}:s)}
function read(p,f){try{return JSON.parse(fs.readFileSync(p,"utf8"))}catch{return f}}function write(p,v){fs.writeFileSync(p,JSON.stringify(v,null,2))}function send(res,code,body){res.writeHead(code,{"content-type":"application/json; charset=utf-8","access-control-allow-origin":"*","access-control-allow-methods":"GET,POST,OPTIONS","access-control-allow-headers":"content-type"});res.end(JSON.stringify(body,null,2))}function body(req){return new Promise(r=>{let d="";req.on("data",c=>d+=c);req.on("end",()=>{try{r(d?JSON.parse(d):{})}catch{r({})}})})}function aid(){return `att_${Date.now()}_${crypto.randomBytes(4).toString("hex")}`}function map(){return Object.fromEntries(scenario.nodes.map(n=>[n.id,n]))}function attempts(){return read(ATT,[])}function autopsy(a,n){const tags={};const strengths=[],weak=[];for(const c of a.choices){for(const t of c.tags||[])tags[t]=(tags[t]||0)+1;if(c.score>0)strengths.push(c.label);if(c.score<0)weak.push(c.label)}return{profile:n.profile,result:n.result,diagnosis:n.diagnosis,scar:n.scar,score_total:a.score_total,top_mistakes:Object.entries(tags).sort((a,b)=>b[1]-a[1]).slice(0,8).map(([tag,count])=>({tag,count})),strengths:strengths.slice(-5),weak_choices:weak.slice(-5),evidence_basis:scenario.source_logic}}
http.createServer(async(req,res)=>{const url=new URL(req.url,`http://${req.headers.host}`);if(req.method==="OPTIONS")return send(res,204,{});if(url.pathname==="/health")return send(res,200,{ok:true,layer:"The Forge",build:BUILD,status:"online",active_scenario:scenario.id,game_mode:"evidence_casefile_engine"});if(url.pathname==="/api/catalog")return send(res,200,{ok:true,build:BUILD,catalog:{module:"second-stake",active_scenario:scenario.id,doctrine:"evidence, story, and cockpit state travel together"}});if(url.pathname==="/api/scenarios")return send(res,200,{ok:true,build:BUILD,scenarios:allScenarios().map(s=>({id:s.id,title:s.title,subtitle:s.subtitle||null,status:s.status,scar:s.scar,module:s.module,scenario_number:s.scenario_number,format:s.format||"locked"}))});if(req.method==="GET"&&url.pathname.startsWith("/api/scenarios/")){const sid=decodeURIComponent(url.pathname.split("/").pop());if(sid!==scenario.id&&sid!==scenario.legacy_id)return send(res,423,{ok:false,error:"Scenario locked"});return send(res,200,{ok:true,build:BUILD,scenario})}if(req.method==="POST"&&url.pathname==="/api/attempts"){const b=await body(req);if(b.scenario_id&&b.scenario_id!==scenario.id&&b.scenario_id!==scenario.legacy_id)return send(res,404,{ok:false,error:"Playable scenario not found"});const start=map().start;const a={attempt_id:aid(),scenario_id:scenario.id,scenario_title:scenario.title,module:scenario.module,status:"in_progress",started_at:new Date().toISOString(),completed_at:null,current_node_id:"start",choices:[],score_total:0,outcome:null,scar_unlocked:null};const list=attempts();list.unshift(a);write(ATT,list);return send(res,201,{ok:true,build:BUILD,attempt:a,node:start,scenario_summary:{id:scenario.id,title:scenario.title,scar:scenario.scar,scenario_number:1,format:scenario.format}})}if(req.method==="POST"&&url.pathname.match(/^\/api\/attempts\/[^/]+\/choice$/)){const attemptId=url.pathname.split("/")[3],b=await body(req),list=attempts(),a=list.find(x=>x.attempt_id===attemptId);if(!a)return send(res,404,{ok:false,error:"Attempt not found"});if(a.status==="complete")return send(res,409,{ok:false,error:"Attempt already complete",attempt:a});const m=map(),node=m[b.node_id||a.current_node_id],ch=(node?.choices||[]).find(c=>c.id===b.choice_id);if(!ch)return send(res,400,{ok:false,error:"Choice not valid"});a.choices.push({at:new Date().toISOString(),node_id:node.id,scene:node.scene,choice_id:ch.id,label:ch.label,next_node_id:ch.next,score:ch.score||0,tags:ch.tags||[],basis:ch.basis||[]});a.score_total+=(ch.score||0);a.current_node_id=ch.next;let next=m[ch.next];if(next?.terminal){const out=autopsy(a,next);a.status="complete";a.completed_at=new Date().toISOString();a.outcome=out;a.scar_unlocked=out.scar;a.top_mistakes=out.top_mistakes;a.strengths=out.strengths;next={...next,outcome:out}}write(ATT,list);return send(res,200,{ok:true,build:BUILD,attempt:a,node:next,complete:a.status==="complete",scar_unlocked:a.scar_unlocked})}if(req.method==="GET"&&url.pathname==="/api/attempts")return send(res,200,{ok:true,build:BUILD,attempts:attempts().slice(0,80).map(a=>({attempt_id:a.attempt_id,scenario_id:a.scenario_id,scenario_title:a.scenario_title,status:a.status,started_at:a.started_at,completed_at:a.completed_at,choices_count:a.choices.length,score_total:a.score_total,scar_unlocked:a.scar_unlocked,profile:a.outcome?.profile||null}))});if(req.method==="GET"&&url.pathname==="/api/progress"){const list=attempts(),done=list.filter(a=>a.status==="complete");return send(res,200,{ok:true,build:BUILD,progress:{total_attempts:list.length,completed_attempts:done.length,scars_unlocked:new Set(done.map(a=>a.scar_unlocked).filter(Boolean)).size}})}return send(res,404,{ok:false,error:"Route not found",build:BUILD})}).listen(PORT,"127.0.0.1",()=>console.log(`The Forge ${BUILD} running on ${PORT}`));
